# First, let me check what demos I currently have for this task
import os, glob, re

def load():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {}
    sessions_file = os.path.join(os.path.dirname(d), os.path.basename(d) + '.jsonl')
    if os.path.exists(sessions_file):
        t = open(sessions_file).read()
    else:
        t = ''
    G = {}
    for match in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = match.groups()
        k = ' '.join([k])  # "Demo pair N input" or "Test input (N)x(M)"
        end_pos = match.end()
        lines = t[end_pos:].split('\n')[:h]
        if k not in G:
            G[k] = [[int(x) for x in r.split()] for r in lines if r.strip()]
    return G

G = load()
print("Loaded grids:", sorted(G.keys()))
